505	    /// Builds the parser for one rendered chunk: the same comment-highlighting
506	    /// base every chunk shares, plus search-match highlighting for exactly
507	    /// that chunk's own matches, read directly from `findState` — which owns
508	    /// the chunk split and computes matches per chunk once per source/query
509	    /// change (see `MarkdownFindState`), rather than this view re-parsing the
510	    /// chunk's plain-text projection on every body evaluation. `baseURL` is
511	    /// threaded through the comment-highlighting base so relative
512	    /// links/images resolve.
513	    private func markdownParser(forChunkAt index: Int) -> any MarkupParser {
514	        let base: any MarkupParser
515	        if commentedAnchors.isEmpty && commentFlashAnchor == nil {
516	            base = AttributedStringMarkdownParser.markdown(baseURL: baseURL)
517	        } else {
518	            base = HighlightingMarkdownParser(
519	                highlightedAnchors: commentedAnchors,
520	                flashingAnchor: commentFlashAnchor,
521	                baseURL: baseURL
522	            )
523	        }
524	        guard findState.isActive, !findState.query.isEmpty else { return base }
525	        let (matches, currentLocalIndex) = findState.chunkMatches(index)
526	        guard !matches.isEmpty else { return base }
527	        return SearchHighlightingMarkdownParser(inner: base, matches: matches, currentMatchIndex: currentLocalIndex)
528	    }
