532	    /// a `NSScrollView`'s document offset to the top when its document view is
533	    /// torn down and rebuilt — exactly what SwiftUI does for an `.id()` change —
534	    /// so a comment add/remove/flash would otherwise scroll the reader back to
535	    /// the top. The offset is captured before the remount and reapplied on the
536	    /// next run-loop turn once the new content has laid out.
537	    private func bumpParseVersionPreservingScroll() {
538	        let offset = scrollController.currentOffset()
539	        parseVersion &+= 1
540	        guard let offset else { return }
541	        DispatchQueue.main.async {
542	            scrollController.restoreOffset(offset)
543	        }
544	    }
