627	    static func chunks(in source: String, collapsibleHeadings: Set<String>) -> [MarkdownDocumentChunk] {
628	        guard !collapsibleHeadings.isEmpty else { return [.plain(source)] }
629	        let headings = headingLines(in: source)
630	        let matchedIndices = headings.indices.filter { collapsibleHeadings.contains(headings[$0].text) }
631	        guard !matchedIndices.isEmpty else { return [.plain(source)] }
