634	        var cursor = source.startIndex
635	        for i in matchedIndices {
636	            let heading = headings[i]
637	            if heading.lineRange.lowerBound > cursor {
638	                chunks.append(.plain(String(source[cursor..<heading.lineRange.lowerBound])))
639	            }
640	            let sectionEnd = (i + 1 < headings.count) ? headings[i + 1].lineRange.lowerBound : source.endIndex
