642	            chunks.append(.collapsible(heading: heading.text, body: body))
643	            cursor = sectionEnd
644	        }
645	        if cursor < source.endIndex {
646	            chunks.append(.plain(String(source[cursor...])))
647	        }
648	        return chunks
649	    }
